import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Quick correlation check for near-duplicates
    corr_matrix = np.corrcoef(feats.x.T)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                correlated_pairs.add((feats.ids[i], feats.ids[j]))

    # Group correlated features
    groups = []
    used = set()
    for fid1, fid2 in correlated_pairs:
        if fid1 not in used and fid2 not in used:
            group = {fid1, fid2}
            used.update(group)
            # Simple extension - just take direct correlations
            for fid1_, fid2_ in correlated_pairs:
                if fid1_ in group or fid2_ in group:
                    group.add(fid1_)
                    group.add(fid2_)
            groups.append(group)

    # Keep representative from each group (highest effect size)
    representative_features = set()
    for group in groups:
        best_fid = max(group, key=lambda fid: abs(np.mean(feats.x[feats.y==1, feats.column(fid)]) - 
                                                  np.mean(feats.x[feats.y==0, feats.column(fid)])))
        representative_features.add(best_fid)

    # Non-correlated features
    non_correlated = set(feats.ids) - representative_features

    # Select drivers by t-statistic
    drivers = []
    t_stats = []
    for fid in feats.ids:
        if fid in representative_features:
            continue
        y0 = feats.x[feats.y==0, feats.column(fid)]
        y1 = feats.x[feats.y==1, feats.column(fid)]
        t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
        t_stats.append((fid, abs(t_stat)))

    # Sort and select top drivers
    sorted_features = sorted(t_stats, key=lambda x: x[1], reverse=True)
    for fid, _ in sorted_features[:MAX_DRIVERS]:
        if fid in non_correlated:
            drivers.append(fid)

    # All features except representatives for regression
    columns = [fid for fid in feats.ids if fid not in representative_features]

    # Products for correlated pairs
    products = []
    for fid1, fid2 in correlated_pairs:
        if fid1 in columns and fid2 in columns:
            products.append((fid1, fid2))

    # Weighted score using mean differences
    loadings = {}
    for fid in columns:
        diff = np.mean(feats.x[feats.y==1, feats.column(fid)]) - np.mean(feats.x[feats.y==0, feats.column(fid)])
        loadings[fid] = diff

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
